def linear_search(sequence, target):
    for index, item in enumerate(sequence):
        if item == target:
            return index
    return -1

def rec_linear_search(sequence, low, high, target):
    if not (0 <= high < len(sequence) and 0 <= low < len(sequence)):
        raise ValueError("Invalid upper or lower bound!")
    if high < low:
        return -1
    if sequence[low] == target:
        return low
    return rec_linear_search(sequence, low + 1, high, target)

def binary_search(sorted_collection, item):
    left = 0
    right = len(sorted_collection) - 1
    result = -1
    while left <= right:
        midpoint = left + (right - left) // 2
        current_item = sorted_collection[midpoint]
        if current_item == item:
            result = midpoint
            right = midpoint - 1
        elif item < current_item:
            right = midpoint - 1
        else:
            left = midpoint + 1
    return result

def bisect_left(sorted_collection, item, lo=0, hi=-1):
    if hi < 0:
        hi = len(sorted_collection)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if sorted_collection[mid] < item:
            lo = mid + 1
        else:
            hi = mid
    return lo

def binary_search_by_recursion(sorted_collection, item, left=0, right=-1):
    if right < 0:
        right = len(sorted_collection) - 1
    if right < left:
        return -1
    midpoint = left + (right - left) // 2
    current_item = sorted_collection[midpoint]
    if current_item == item:
        return midpoint
    elif item < current_item:
        return binary_search_by_recursion(sorted_collection, item, left, midpoint - 1)
    else:
        return binary_search_by_recursion(sorted_collection, item, midpoint + 1, right)

def bubble_sort_iterative(collection):
    length = len(collection)
    for i in reversed(range(length)):
        swapped = False
        for j in range(i):
            if collection[j + 1] < collection[j]:
                swapped = True
                collection[j], collection[j + 1] = collection[j + 1], collection[j]
        if not swapped:
            break
    return collection

def bubble_sort_recursive(collection):
    length = len(collection)
    swapped = False
    for i in range(length - 1):
        if collection[i + 1] < collection[i]:
            collection[i], collection[i + 1] = collection[i + 1], collection[i]
            swapped = True
    return collection if not swapped else bubble_sort_recursive(collection)

def selection_sort(collection):
    length = len(collection)
    for i in range(length - 1):
        min_index = i
        for k in range(i + 1, length):
            if collection[k] < collection[min_index]:
                min_index = k
        if min_index != i:
            collection[i], collection[min_index] = collection[min_index], collection[i]
    return collection

def insertion_sort(collection):
    for insert_index in range(1, len(collection)):
        insert_value = collection[insert_index]
        while insert_index > 0 and insert_value < collection[insert_index - 1]:
            collection[insert_index] = collection[insert_index - 1]
            insert_index -= 1
        collection[insert_index] = insert_value
    return collection

def merge_sort(collection):
    def merge(left, right):
        result = []
        while left and right:
            if right[0] < left[0]:
                result.append(right.pop(0))
            else:
                result.append(left.pop(0))
        result.extend(left)
        result.extend(right)
        return result
    if len(collection) <= 1:
        return collection
    mid_index = len(collection) // 2
    return merge(merge_sort(collection[:mid_index]), merge_sort(collection[mid_index:]))

from queue import Queue

class Graph:
    def __init__(self):
        self.vertices = {}

    def bfs(self, start_vertex):
        visited = set()
        queue = Queue()
        visited.add(start_vertex)
        queue.put(start_vertex)
        while not queue.empty():
            vertex = queue.get()
            for adjacent_vertex in self.vertices[vertex]:
                if adjacent_vertex not in visited:
                    queue.put(adjacent_vertex)
                    visited.add(adjacent_vertex)
        return visited

def depth_first_search(graph, start):
    explored, stack = set(start), [start]
    while stack:
        v = stack.pop()
        explored.add(v)
        for adj in reversed(graph[v]):
            if adj not in explored:
                stack.append(adj)
    return explored

import heapq

def dijkstra(graph, start, end):
    heap = [(0, start)]
    visited = set()
    costs = {start: 0}
    while heap:
        cost, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        if u == end:
            return cost
        for v, c in graph[u]:
            if v in visited:
                continue
            next_cost = cost + c
            if next_cost < costs.get(v, float("inf")):
                costs[v] = next_cost
                heapq.heappush(heap, (next_cost, v))
    return -1
